import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"라벨렌 전기: 겨울선 (Ravelen Chronicles: The Winter Line) — 웹 빌드 역설계 백과사전","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Ref-Ravelen-Chronicles.md","filePath":"rules/Ref-Ravelen-Chronicles.md"}'),a={name:"rules/Ref-Ravelen-Chronicles.md"};function l(n,t,i,s,c,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p></div><blockquote><p>자동 생성 문서입니다 — 원본은 저장소 내부 조사 문서(<code>ravelen-chronicles.md</code>)에서 파생했으며 금지 용어는 위키 공개 기준에 맞게 치환했다. 실측·판독 기준일 2026-09-07.</p></blockquote><h1 id="라벨렌-전기-겨울선-ravelen-chronicles-the-winter-line-—-웹-빌드-역설계-백과사전" tabindex="-1">라벨렌 전기: 겨울선 (Ravelen Chronicles: The Winter Line) — 웹 빌드 역설계 백과사전 <a class="header-anchor" href="#라벨렌-전기-겨울선-ravelen-chronicles-the-winter-line-—-웹-빌드-역설계-백과사전" aria-label="Permalink to &quot;라벨렌 전기: 겨울선 (Ravelen Chronicles: The Winter Line) — 웹 빌드 역설계 백과사전&quot;">​</a></h1><blockquote><p>Project EMBER, 웹 콘테스트 빌드(데스크톱 1920×1080). <a href="https://ravelen-chronicles-web.vercel.app/" target="_blank" rel="noreferrer">https://ravelen-chronicles-web.vercel.app/</a> 배포본을 2026-09-07 정적 분석(번들 판독)과 실측 플레이로 역설계했다. 한국어 1차 언어(en-US·zh-CN 로케일 동봉)의 GBA 파이어 엠블렘 계보 <strong>턴제 SRPG</strong>로, 캠페인 허브·인연·사기·항복·병참·거점을 얹었다.</p><p><strong>표기</strong>: <code>[코드]</code>는 배포 번들에서 읽어낸 상수·수식(경로는 <code>assets/&lt;청크&gt;.js</code> 기준), <code>[UI]</code>는 실측 플레이 화면·i18n 문자열, <code>[추론]</code>은 그 둘을 종합한 구조 해석, <code>[미확인]</code>은 이번 판독에서 위치를 못 찾은 항목이다. 출처 목록은 부록.</p><p><strong>이 문서가 존재하는 이유</strong>: 잔선은 2026-09-07부로 전투를 실시간·진형·카드 기반으로 전환한다(<a href="https://github.com/islee23520/seoul-kenshi/blob/main/Intent.md" target="_blank" rel="noreferrer">Intent.md</a> 결정 3). 이 게임은 <strong>턴제 SRPG 쪽의 마지막 정밀 참조</strong>이며, 여기서 가져갈 것은 턴 구조가 아니라 사기·항복·지휘조·인연·병참·예고된 증원 같은 <strong>전투 바깥 계약</strong>이다.</p></blockquote><h2 id="_1-정체와-기술-스택" tabindex="-1">1. 정체와 기술 스택 <a class="header-anchor" href="#_1-정체와-기술-스택" aria-label="Permalink to &quot;1. 정체와 기술 스택&quot;">​</a></h2><ul><li><strong>빌드</strong>: Vite + rolldown 번들. 진입 <code>game-*.js</code>가 <code>main-*.js</code>(전투 런타임 413KB)·<code>game-rules~main-*.js</code>(순수 규칙 엔진 386KB)·<code>campaign-*.js</code>(캠페인 210KB)·<code>game-ui-*.js</code>(279KB)를 지연 로드. 전장 JSON 24개는 빌드 시 JS 청크로 변환(<code>ch01-ash-village-*.js</code> 등). [코드]</li><li><strong>표현</strong>: DOM 스테이지(1920×1080 고정, CSS 변수 <code>--stage-scale</code>로 축소) 위에 전투 캔버스 1440×810. 유닛은 캐릭터별 스프라이트 시트(idle·walk·map-idle·attack·hit·defeat·dash·victory·heal) 795개 청크, VFX는 512px 프레임 잉크 시트 31종을 색조 합성. 지면은 <code>isotool-art/ground/*</code> 타일. [코드][UI]</li><li><strong>저장</strong>: <code>localStorage</code> 슬롯 저장·불러오기, 전투 중 저장·되감기. [코드][UI]</li><li><strong>접근성·조작</strong>: 좌클릭 선택·이동·확정, 우클릭/Esc 취소, Enter/Space 제자리 행동, M 음소거, T 지형 전술 보기, O 전체 목표. [UI]</li><li><strong>로케일</strong>: <code>class-data-*.js</code>가 ko-KR 227키의 i18n 사전(이름과 달리 클래스 데이터가 아님). [코드]</li></ul><h2 id="_2-콘텐츠-규모" tabindex="-1">2. 콘텐츠 규모 <a class="header-anchor" href="#_2-콘텐츠-규모" aria-label="Permalink to &quot;2. 콘텐츠 규모&quot;">​</a></h2><ul><li><strong>본편 18장 + 외전 6장</strong>: ch01 재가 내린 마을 → ch02 끊어진 봉화 → ch03 두 군기의 사이 → ch04 비 없는 나루 → ch05 소금길 → ch06 이름 없는 무덤 → ch07 성문 안의 적 → ch08 겨울선 → ch09 수도의 증언 → ch10 잿길 후퇴 → ch11 강 건너 군기 → ch12 열린 감옥 → ch13 세 봉수 → ch14 굶주린 요새 → ch15 귀환군 → ch16 수도의 새벽 → ch17 불씨를 든 사람들 → ch18 마지막 봉수. 외전 side03·05·07·10·12·15. [코드] (한국어 장 제목은 4장까지 UI 확인, 이후는 전장 ID의 번역이므로 [추론])</li><li><strong>명명 인물 25명</strong>(세란 덴·로안 페르·미라 켈·토반 로크·이네스 바르·네브 아실·유라 사엔·브람 코르·타린 모·엘다 모른·나디아 펠·카엘 오르트·마엘 로사·시브 레카·오르나 베이·레오 안트·베사 룬·이사 벤·코렌 다·듀란 헤트·리에 소른·에녹 펠·사라 오르트·헤스 나르·칼데르 정위). [코드]</li><li><strong>적 병종 키트</strong>: sword-guard·spear-phalanx·watch-archer·axe-raider·wing-scout·courier-cavalry·signal-mage·engineer-team·siege-team·field-medic·cavalry-archer·signal-soldier가 장별 세력(칼데르·오르사·소금길·의회·감옥·요새·수도…)으로 변주. 민간인·중립 유닛(주민·탈영병·귀환자·민병) 별도. [코드]</li><li><strong>세계</strong>: 칼데르 왕국과 오르사 동맹 사이의 에르모스 회랑(강·곡창·봉수탑). [UI]</li></ul><h2 id="_3-모드와-실패-규칙" tabindex="-1">3. 모드와 실패 규칙 <a class="header-anchor" href="#_3-모드와-실패-규칙" aria-label="Permalink to &quot;3. 모드와 실패 규칙&quot;">​</a></h2><ul><li><strong>난이도</strong> 이야기/표준/숙련, <strong>손실 모드</strong> 서사/전술/클래식, <strong>철인</strong> 토글. [UI]</li><li><strong>되감기</strong>: 직전 아군 페이즈 시작 상태 복원. 서사·전술 모드에서만. [UI]</li><li><strong>턴 제한</strong> 실패 조건이 존재하며 잔여 3턴부터 카운트다운 효과음. [코드]</li><li>난이도별 수치 보정과 손실 모드별 사망 처리는 [미확인].</li></ul><h2 id="_4-유닛-모델" tabindex="-1">4. 유닛 모델 <a class="header-anchor" href="#_4-유닛-모델" aria-label="Permalink to &quot;4. 유닛 모델&quot;">​</a></h2><ul><li><strong>스탯 9종</strong>: <code>hp, strength, magic, skill, speed, luck, defense, resistance, constitution</code>. [코드]</li><li><strong>무기</strong>: <code>might, hit, critical, weight, range[min,max], rank(E…), type</code>. 타입은 sword·lance·axe·bow·dagger·tome·staff·tool. <code>effectiveness</code>가 이동 타입 하나를 지정. 비무장 방어는 might 0·range [0,0]의 도구로 취급(반격 불가). [코드]</li><li><strong>이동 타입</strong>: foot·mounted·armour·flying. 기병은 얕은 물 진입 불가. [코드][UI]</li><li><strong>클래스 특기</strong>(예): 정면 승부(사거리 1 공격 시 공격 +1·명중 +10·피해 감소 1), 고립 돌파(인접 2칸 내 아군 0일 때 +1), 대기 장창(방어 시 기병 상대 +2), 철창 반격(기병 상대 피해 감소 2), 균열(중장·요새 상대 +2), 고정 사격(활·미이동 시 +1·명중 +15). <code>master-</code> 접두 상위판 존재. [코드]</li><li><strong>단검+숲 표식</strong>: 숲에서 단검으로 공격하면 상대에게 다음 이동 페널티와 회피 페널티 표식. 도로 위 피격 시 이동 페널티. [코드]</li></ul><h2 id="_5-전투-공식-game-rules-main" tabindex="-1">5. 전투 공식 (<code>game-rules~main</code>) <a class="header-anchor" href="#_5-전투-공식-game-rules-main" aria-label="Permalink to &quot;5. 전투 공식 (`game-rules~main`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>식</th><th>비고</th></tr></thead><tbody><tr><td>무기 상성</td><td>sword &gt; axe &gt; lance &gt; sword</td><td>우세 +1 (공격 ×2 = +2, 명중 +15), 열세 반대. bow·dagger·tome·staff 중립</td></tr><tr><td>공격 속도(AS)</td><td><code>speed − max(0, weight − constitution)</code></td><td></td></tr><tr><td>회피</td><td><code>AS×2 + luck + 지형 회피 + 보정</code></td><td></td></tr><tr><td>명중(원시)</td><td><code>무기 hit + skill×2 + floor(luck/2) + 상성 15 + 보정 − 상대 회피</code> → 0..100 clamp</td><td>지팡이는 <code>85 + hit</code></td></tr><tr><td>명중(표시·판정)</td><td>원시치 t≤50: <code>round(t(2t+1)/100)</code>, t&gt;50: <code>n=198−2t</code>, <code>round(100 − (n+1)(n+2)/200)</code></td><td>2RN 곡선 — 표시값과 실제 판정이 같다는 튜토리얼 문구와 일치</td></tr><tr><td>피해</td><td><code>max(0, (str 또는 mag) + might + 상성×2 + 특효 5 + 공격 보정 − (def 또는 res) − 피해 감소)</code></td><td>tome·staff는 mag/res, 지팡이 might는 절반</td></tr><tr><td>치명</td><td><code>무기 crit + floor(skill/2) + 보정 − 상대 luck − 치명 회피</code> → 0..50 clamp</td><td></td></tr><tr><td>추격(2회 공격)</td><td><code>AS ≥ 상대 AS + 4</code></td><td>반격 가능·사거리 내일 때만</td></tr><tr><td>타격 순서</td><td>공격자 → (반격) → (공격자 추격) → (방어자 추격)</td><td></td></tr></tbody></table><p>[코드] 모든 항목. 사거리 밖·도구 무기는 피해 0·반격 불가.</p><h2 id="_6-지형" tabindex="-1">6. 지형 <a class="header-anchor" href="#_6-지형" aria-label="Permalink to &quot;6. 지형&quot;">​</a></h2><table tabindex="0"><thead><tr><th>지형</th><th>이동 비용</th><th>전투 보정</th></tr></thead><tbody><tr><td>평지·도로·다리</td><td>1</td><td>없음</td></tr><tr><td>숲</td><td>2</td><td>회피 +15 (비행 제외)</td></tr><tr><td>요새</td><td>2</td><td>방어 +2</td></tr><tr><td>얕은 물</td><td>2</td><td>없음, 기병 진입 불가</td></tr><tr><td>고지</td><td>—</td><td>낮은 곳에서의 원거리 공격에만 회피 +10 (인접·같은 고지·비행 제외)</td></tr><tr><td>깊은 물·장애물</td><td>0(불가)</td><td>—</td></tr></tbody></table><p>[코드] 튜토리얼 문구는 숲 회피 +20이라 적혀 있어 규칙 엔진(+15)과 <strong>불일치</strong>. [UI][코드]</p><h2 id="_7-사기와-항복" tabindex="-1">7. 사기와 항복 <a class="header-anchor" href="#_7-사기와-항복" aria-label="Permalink to &quot;7. 사기와 항복&quot;">​</a></h2><ul><li><strong>아군 사기</strong>: 기본 60, 0..100 clamp. 40 미만 경고, 80 이하에서 조건 충족 시 턴당 +5 회복(상한 80). <strong>0이면 와해</strong> — 지휘 명령 잠금·인연 명령 무효. [코드]</li><li><strong>적 지휘관 사기</strong>(전장별): 기본 60(한 전장은 40). 적 격파당 사기 손실 5~10, 격파 누적 손실 상한 10~40, 지정 목표 완료 손실, 지휘관 HP 임계 손실, 캠페인 트랙 손실. [코드]</li><li><strong>항복 3조건</strong>: 사기 ≤ <code>moraleAtMost</code>(전장별 15~50) <strong>그리고</strong> 지휘관 HP% ≤ 임계 <strong>그리고</strong> 퇴로 엄호. 셋 다 맞으면 항복 확정. [UI][코드] 임계 HP%는 전장별 값이라 [미확인].</li><li><strong>사기 사건</strong>: 손실·회복·0 도달·40 미만 진입에 각각 효과음. [코드]</li></ul><h2 id="_8-지휘조와-인연" tabindex="-1">8. 지휘조와 인연 <a class="header-anchor" href="#_8-지휘조와-인연" aria-label="Permalink to &quot;8. 지휘조와 인연&quot;">​</a></h2><ul><li><strong>지휘조(formation groups)</strong>: 리더의 <code>leadership</code> 값이 지휘 범위. 튜토리얼 기준 세란 3칸. 같은 지휘조가 범위 안이면 협공·명령 사용. 독립 임무 유닛(유라)은 혜택 없음. [UI][코드]</li><li><strong>인연 5유형 × 등급 C/B/A</strong>: [코드]</li></ul><table tabindex="0"><thead><tr><th>유형</th><th>트리거</th><th>C</th><th>B</th><th>A 결의(전투당 1회)</th></tr></thead><tbody><tr><td>수호</td><td>피격</td><td>피해 −3</td><td>피해 −5·사기 손실 −5</td><td>+ 생존 후 후퇴</td></tr><tr><td>협공</td><td>공격 예측</td><td>명중 +10</td><td>명중 +10·피해 +1</td><td>+ 반대편 재배치</td></tr><tr><td>기동</td><td>행동 후</td><td>자리 교환</td><td>교환 후 이동 1</td><td>+ 인접 이동</td></tr><tr><td>격려</td><td>명령</td><td>사기 +5</td><td>사기 +10·약화 1턴 단축</td><td>+ 행동 회복</td></tr><tr><td>통찰</td><td>위협 예측</td><td>기술·공격 범위 공개</td><td>(치명 회피 등)</td><td>—</td></tr></tbody></table><ul><li>사용 한도는 턴/페이즈/전투 단위. 인연점은 장마다 상한(&quot;장 상한&quot;)이 있고, 결말은 연인/맹우 선택. 인연 대화는 6개 청크(약 650KB)로 별도 적재. [코드]</li></ul><h2 id="_9-병참·거점·장치·증원" tabindex="-1">9. 병참·거점·장치·증원 <a class="header-anchor" href="#_9-병참·거점·장치·증원" aria-label="Permalink to &quot;9. 병참·거점·장치·증원&quot;">​</a></h2><ul><li><strong>병참 준비안</strong>: 다음 전장에 대한 한 번뿐인 준비. 서로 다른 준비안 최대 2개, 출격 시 차감, 고르지 않아도 출격 가능. [UI]</li><li><strong>거점</strong>: 점령 즉시 효과. 감시탑은 <strong>다음 증원 위치를 미리 드러내고</strong>, 예고 칸을 점유하면 출현에 대비. [UI][코드]</li><li><strong>장치</strong>: 수문(물이 빠진 구간이 평지로), 문, 봉수·중계 신호, 곡물·보급 수레, 기록·명부, 감옥·막사, 군기·집결 깃발, 화재(경고→발화). 인접한 행동 가능 아군이 행동을 소비해 조작. [UI][코드]</li><li><strong>증원 웨이브</strong>: <code>pendingWaves</code>·<code>warnedWaveIndexes</code>로 예고 후 도착. [코드]</li><li><strong>캠페인 허브</strong>: 명부·인연·편성(지휘조 편집)·슬롯 저장·장 선택·에필로그. [UI][코드]</li><li>경험치·레벨업·승급 수치는 [미확인] (레벨업 처리 함수와 &quot;승급&quot; 문자열 존재만 확인).</li></ul><h2 id="_10-잔선-적용-실시간-전환-관점" tabindex="-1">10. 잔선 적용 (실시간 전환 관점) <a class="header-anchor" href="#_10-잔선-적용-실시간-전환-관점" aria-label="Permalink to &quot;10. 잔선 적용 (실시간 전환 관점)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>라벨렌</th><th>잔선에서의 형태</th><th>판단</th></tr></thead><tbody><tr><td>아군 사기 60/40/80/0 + 적 지휘관 사기</td><td>실시간 사기 게이지 — 0이면 명령 잠금·궤주</td><td>채택</td></tr><tr><td>항복 3조건(사기·지휘관 HP·퇴로)</td><td>궤주 대신 <strong>항복</strong> 경로 — 포획·영입 계약과 직결</td><td>채택</td></tr><tr><td>지휘조·지휘 범위</td><td>진형 리더의 지휘 반경 안에서만 카드·협공 유효</td><td>채택</td></tr><tr><td>인연 5유형·등급·전투당 1회 결의</td><td><strong>관계 카드</strong> — 인물 쌍의 관계 등급이 카드 효과를 정함</td><td>채택</td></tr><tr><td>병참 준비안 최대 2·출격 시 차감</td><td>출격 전 <strong>거점 카드 슬롯 2</strong></td><td>채택</td></tr><tr><td>감시탑 증원 예고·예고 칸 점유</td><td>예고된 위협(ITB 계보) — 실시간에서도 지도에 예고 표시</td><td>채택</td></tr><tr><td>장치 행동(수문·문·봉수)</td><td>진형이 인접하면 카드로 조작</td><td>채택</td></tr><tr><td>턴·페이즈·되감기·추격(AS+4)</td><td>실시간 틱으로 대체 — 되감기 없음, 공격 간격으로 치환</td><td>거부</td></tr><tr><td>9스탯 + 2RN 명중</td><td>판정 수치를 소수로 압축(SoS식) 여부는 별도 결정</td><td>보류</td></tr><tr><td>무기 삼각 상성</td><td>병종 상성(SoS Slayer 특성)으로 치환</td><td>대체</td></tr></tbody></table><h2 id="부록-a-판독-근거-위치" tabindex="-1">부록 A. 판독 근거 위치 <a class="header-anchor" href="#부록-a-판독-근거-위치" aria-label="Permalink to &quot;부록 A. 판독 근거 위치&quot;">​</a></h2><ul><li>전투 공식: <code>game-rules~main-BQmJC_0o.js</code>(beautify 기준 L1850–1995: 상성 <code>en</code>, AS <code>on</code>, 회피 <code>sn</code>, 2RN <code>cn</code>, 피해·명중·치명 <code>dn</code>, 왕복 <code>fn</code>, 지형 보정 <code>pn</code>), 스탯 생성자 <code>D</code> L214.</li><li>지형 이동 비용: 같은 파일 L560–600 전장 정의 내 <code>terrain</code>.</li><li>사기 상수: 같은 파일 L1492–1747(전장별 <code>baseMorale·moraleAtMost·moraleLossPerDefeatedEnemy·maximumDefeatMoraleLoss</code>), 아군 사기 L3065–3120.</li><li>인연 효과: <code>bond-effects-tA061RX9.js</code> 전체.</li><li>전투 예측·지휘조·특기 합산: <code>main-CHP8nOHi.js</code> <code>FT</code>·<code>sT</code>·<code>Fw</code>·<code>rT</code>(beautify L≈247700–248200).</li><li>콘텐츠 ID·청크 맵: <code>game-Cwt9-13I.js</code> <code>__vite__mapDeps</code>.</li><li>실측 화면: 타이틀(게임 시작·불러오기·설정, 조작 안내), 프롤로그 대화(에르모스 회랑), 전투 화면 DOM(지형 전술 보기 T, 목표 O, 전투 메뉴).</li></ul><h2 id="부록-b-출처" tabindex="-1">부록 B. 출처 <a class="header-anchor" href="#부록-b-출처" aria-label="Permalink to &quot;부록 B. 출처&quot;">​</a></h2><ul><li><strong>R-01</strong> <a href="https://ravelen-chronicles-web.vercel.app/" target="_blank" rel="noreferrer">https://ravelen-chronicles-web.vercel.app/</a> 배포 HTML·번들(2026-09-07 취득). 번들은 분석용으로만 임시 디렉터리에 두었고 저장소에 반입하지 않았다.</li><li><strong>R-02</strong> 같은 배포본 i18n 사전(<code>class-data-*.js</code> ko-KR) — 튜토리얼·인연·병참·항복 설명문.</li><li><strong>R-03</strong> 실측 플레이(타이틀 → 프롤로그 → 1장 진입) 스냅샷·스크린샷, 2026-09-07.</li></ul>',32)])])}const m=e(a,[["render",l]]);export{u as __pageData,m as default};
